record.field:
pharmacist_group = env.ref('base_hospital_management.group_pharmacist', raise_if_not_found=False)
if pharmacist_group:
    orderpoints = env['stock.warehouse.orderpoint'].search([])
    low_items = []
    for op in orderpoints:
        qty = op.product_id.qty_available
        if qty <= op.product_min_qty:
            low_items.append(f'{op.product_id.name}: {qty} (min: {op.product_min_qty})')
    if low_items:
        users = env['res.users'].search([('groups_id', 'in', pharmacist_group.ids)])
        for user in users:
            if user.partner_id.email:
                env['mail.mail'].create({
                    'subject': 'Low Stock Alert — Pharmacy',
                    'body_html': '<p>The following medicines are below minimum stock level:</p><ul>' +
                                 ''.join(f'<li>{i}</li>' for i in low_items) + '</ul>',
                    'email_to': user.partner_id.email,
                }).send()
